using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace Unice
{
    /// <summary>
    /// Where each registered map lives in the project (<c>Domain/Maps/Map&lt;Name&gt;.cs</c>) and how its file is regenerated by
    /// <see cref="MapCodeWriter"/>. To register a new map, add its entry to <see cref="Entries"/> next to its <see cref="Maps"/> registration.
    /// </summary>
    public static class MapSourceFiles
    {
        const string MapsFolder = "Assets/Unice/Scripts/Domain/Maps/";
        const string RegenerateItem = "Unice/Mapas/Regerar código dos mapas";

        /// <summary>One map's file: the class name, the header notes worth keeping, and static members the definition itself does not hold.</summary>
        readonly struct Entry
        {
            public readonly string id, className, comment, extraMembers;
            public Entry(string id, string className, string comment, string extraMembers = null)
            { this.id = id; this.className = className; this.comment = comment; this.extraMembers = extraMembers; }
        }

        static readonly Entry[] Entries =
        {
            new Entry(MapHouse.Id, nameof(MapHouse),
                "The house: the original 12-room layout. The original 30 furniture entries keep their exact\n" +
                "array order/coordinates — Art/manifest.json's furn[].i indexes into Map.Furniture positionally,\n" +
                "so reordering or inserting among them would point existing art at the wrong piece (new pieces go at the end).\n" +
                "Some originally-decorative pieces (dresser, dollhouse, shelves, armchair, commode, fireplace,\n" +
                "cabinet, ktable, planters, pshelves, tank) gained a hiding side; sink/stove didn't (too small)."),
            new Entry(MapLobisomem.Id, nameof(MapLobisomem),
                "The werewolf story (docs/stories/lobisomem.md): the backyard of the aunt's house in the Bahia countryside, at night, drawn from\n" +
                "the author's own floor plan. The house itself was off limits in the story, so it is a hole in the map (nobody can walk into it\n" +
                "or see through it); the yard is the open ground around it, split into overlapping areas with no walls or doors.\n" +
                "The only light is the balcony where the kids were listening, so it is the one warm floor in a very dark yard.\n" +
                "The kids start on the balcony; the howl comes from the dark end of the aunt's garden, as far from them as the yard allows.\n" +
                "Plan coordinates were scaled to the 1720×1180 world (the house map's size) for a comparable round length.\n" +
                "Room order matters: the game names the first area a point is in, so the balcony comes first to win where areas overlap.\n" +
                "Hiding spots (14) come first in the furniture list, the decorative clothesline (1) last.\n" +
                "Entry is the dark end of the garden; spawn is the balcony, where the story was being told.",
                "        /// <summary>The house: not walkable, not see-through. Areas are kept 22 px away from it (the \"wall\"). Kept here to document the hole.</summary>\n" +
                "        public static readonly RectF House = new RectF(557, 322, 648, 230);"),
            new Entry(MapRua.Id, nameof(MapRua),
                "The street story (docs/stories/rua.md): the old square of the author's town, seen in a satellite print, where the cousins ran around\n" +
                "playing hide-and-seek. Two streets run side by side (Rua do Mocambo and Rua Monsenhor José Magalhães) around a long island full of\n" +
                "trees, join at one end and open into a wide paved square at the other. Going into the houses was forbidden, so every house is wall:\n" +
                "the walkable ground is only the band of streets, island and square, made of overlapping areas with no doors.\n" +
                "At the east end of the paved square stands the church, also off limits, with the cross in front of it and a phone booth beside.\n" +
                "The print was turned on its side (its top is the west end) and stretched across to fit the 1720×1180 world.\n" +
                "Room order matters: the game names the first area a point is in, so the most specific areas come first.\n" +
                "Hiding spots (19), all of the furniture. Entry is the far corner of the paved square, in front of the church;\n" +
                "spawn is the street in front of grandma's house.",
                "        /// <summary>The church closing the paved square: not walkable, not see-through. Kept here to document the hole.</summary>\n" +
                "        public static readonly RectF Church = new RectF(1582, 300, 98, 600);"),
        };

        /// <summary>Rewrites every registered map's file from <see cref="Maps"/>; a plain static method, so a batch run can call it with <c>-executeMethod Unice.MapSourceFiles.RegenerateAll</c>.</summary>
        [MenuItem(RegenerateItem)]
        public static void RegenerateAll()
        {
            foreach (var entry in Entries) Save(Maps.ById(entry.id), entry);
            AssetDatabase.Refresh();
            Debug.Log("Unice: map code regenerated for " + Entries.Length + " maps.");
        }

        /// <summary>Writes one map's file (UTF-8 without BOM, LF endings, like the rest of the Domain sources).</summary>
        static void Save(MapDefinition map, Entry entry)
        {
            File.WriteAllText(PathOf(entry.className), MapCodeWriter.Write(map, entry.className, entry.comment, entry.extraMembers), new UTF8Encoding(false));
        }

        /// <summary>Project-relative path of a map's source file.</summary>
        public static string PathOf(string className) => MapsFolder + className + ".cs";
    }
}
